+            <li class="list-group-item d-flex justify-content-between align-items-start">
+                <span>@n.Message</span>
+                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
+            </li>
+        }
+    </ul>
+}
+
+@code {
+    private CancellationTokenSource? _cts;
+
+    [PersistentState]
+    public List<Notification>? _notifications { get; set; }
+
+    protected override async Task OnInitializedAsync()
+    {
+        // ??= ensures we only fetch when state wasn't restored from prerender
+        _notifications ??= await NotificationService.GetAllAsync();
+    }
+
+    protected override void OnAfterRender(bool firstRender)
+    {
+        if (firstRender)
+        {
+            // OnAfterRender is never called during prerender,
+            // so the polling loop only starts once the page is truly interactive.
+            _cts = new CancellationTokenSource();
+            _ = PollForNotificationsAsync(_cts.Token);
+        }
+    }
+
+    private async Task PollForNotificationsAsync(CancellationToken ct)
+    {
+        while (!ct.IsCancellationRequested)
+        {
+            try
+            {
+                await Task.Delay(TimeSpan.FromSeconds(5), ct);
+
+                // Simulate a new notification arriving on each poll
+                NotificationService.SimulateIncoming();
+
+                var lastId = _notifications?.Count > 0
+                    ? _notifications.Max(n => n.Id)
+                    : 0;
+
+                var newer = await NotificationService.GetNewerThanAsync(lastId);
+                if (newer.Count > 0)
+                {
+                    _notifications ??= new();
+                    _notifications.AddRange(newer);
+                    await InvokeAsync(StateHasChanged);
+                }
+            }
+            catch (OperationCanceledException)
+            {
+                break;
+            }
+        }
+    }
+
+    public void Dispose()
+    {
+        _cts?.Cancel();
+        _cts?.Dispose();
+    }
+}
