namespace BlazorApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications = new();
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed with initial fake data
        _notifications.Add(new(NextId(), "Welcome to the notification center!", DateTime.UtcNow.AddMinutes(-10)));
        _notifications.Add(new(NextId(), "Your profile was updated successfully.", DateTime.UtcNow.AddMinutes(-5)));
        _notifications.Add(new(NextId(), "New feature: dark mode is now available.", DateTime.UtcNow.AddMinutes(-2)));
    }

    public Task<List<Notification>> GetAllAsync()
    {
        lock (_lock)
        {
            return Task.FromResult(_notifications.ToList());
        }
    }

    public Task<List<Notification>> GetNewerThanAsync(int lastSeenId)
    {
        lock (_lock)
        {
            return Task.FromResult(
                _notifications.Where(n => n.Id > lastSeenId).ToList());
        }
    }

    /// <summary>Simulates a new notification arriving.</summary>
    public void SimulateIncoming()
    {
        var messages = new[]
        {
            "Someone commented on your post.",
            "You have a new follower!",
            "Server deployment completed.",
            "Reminder: standup in 15 minutes.",
            "Your build succeeded.",
            "New pull request requires your review.",
        };

        lock (_lock)
        {
            var id = NextId();
            var msg = messages[id % messages.Length];
            _notifications.Add(new(id, msg, DateTime.UtcNow));
        }
    }

    private int NextId() => _nextId++;
}

